// "iso4217.json generated by a committed script; a test checks the generated
// file" (P3-02 ruling). The generator's pure transform runs offline on the
// committed source snapshot and must reproduce data/iso4217.json byte for
// byte, so a hand edit to the JSON fails here.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import {
  buildDocument,
  compareEntries,
  fromMirrorCsv,
  fromSixXml,
  parseCsv,
  serialize,
} from "../scripts/iso4217-lib.mjs";

const dataDir = path.join(import.meta.dirname, "../data");
const csv = readFileSync(path.join(dataDir, "source/codes-all.csv"), "utf8");
const sourceJson: unknown = JSON.parse(
  readFileSync(path.join(dataDir, "source/source.json"), "utf8"),
);
const committed = readFileSync(path.join(dataDir, "iso4217.json"), "utf8");

describe("data/iso4217.json is generated, not hand-edited", () => {
  it("the snapshot's SHA-256 equals the one recorded in source.json", () => {
    const sha = createHash("sha256").update(csv).digest("hex");
    expect(sourceJson).toEqual(expect.objectContaining({ sha256: sha }));
    expect(sha).toBe(
      "c4b6829a966f0564e77dc6c2d100d268cce61b30f7637bf3d5ec626b0393407f",
    );
  });

  it("regenerating from the snapshot reproduces the committed file byte for byte", () => {
    const regenerated = serialize(
      buildDocument(fromMirrorCsv(csv), sourceJson),
    );
    expect(regenerated).toBe(committed);
  });

  it("a one-character edit to the JSON is caught by the same comparison", () => {
    const tampered = committed.replace(
      '"code": "BHD",\n      "numeric": "048",\n      "name": "Bahraini Dinar",\n      "exponent": 3',
      '"code": "BHD",\n      "numeric": "048",\n      "name": "Bahraini Dinar",\n      "exponent": 2',
    );
    expect(tampered).not.toBe(committed);
    const regenerated = serialize(
      buildDocument(fromMirrorCsv(csv), sourceJson),
    );
    expect(regenerated).not.toBe(tampered);
  });
});

// Owner's SIX cross-check, 2026-10-14: KMF "Comorian Franc " (trailing space)
// differed from SIX. Names are normalised (trim, every whitespace run to one
// U+0020) by the one helper both sources go through.
describe("currency names in data/iso4217.json are whitespace-normalised", () => {
  const doc: unknown = JSON.parse(committed);
  const names = (doc as { currencies: { code: string; name: string }[] })
    .currencies;
  const offending = (bad: (name: string) => boolean) =>
    names.filter((e) => bad(e.name)).map((e) => e.code);

  it("covers every entry", () => {
    expect(names.length).toBeGreaterThan(300);
  });

  it("every name equals its trim(): no leading or trailing whitespace", () => {
    expect(offending((n) => n !== n.trim())).toEqual([]);
    expect(offending((n) => /^\s|\s$/u.test(n))).toEqual([]);
  });

  it("no name contains a run of two or more whitespace characters", () => {
    expect(offending((n) => /\s{2,}/u.test(n))).toEqual([]);
  });

  it("no name contains a control character", () => {
    expect(offending((n) => /\p{Cc}/u.test(n))).toEqual([]);
  });

  it("no name contains any \\s other than U+0020", () => {
    expect(offending((n) => /[^\S ]/u.test(n))).toEqual([]);
  });

  it("KMF and ZWL carry the normalised names", () => {
    const byCode = new Map(names.map((e) => [e.code, e.name]));
    expect(byCode.get("KMF")).toBe("Comorian Franc");
    expect(byCode.get("ZWL")).toBe("Zimbabwe Dollar");
  });
});

describe("parseCsv", () => {
  it("handles quoted fields with commas and doubled quotes", () => {
    expect(parseCsv('a,"b, c","d ""e"""\n1,2,3\n')).toEqual([
      ["a", "b, c", 'd "e"'],
      ["1", "2", "3"],
    ]);
  });

  it("accepts CRLF line ends and a missing final newline", () => {
    expect(parseCsv("a,b\r\n1,2")).toEqual([
      ["a", "b"],
      ["1", "2"],
    ]);
  });

  it("fails on an unterminated quote", () => {
    expect(() => parseCsv('a,"b\n')).toThrow();
  });
});

const header =
  "Entity,Currency,AlphabeticCode,NumericCode,MinorUnit,WithdrawalDate\n";

describe("fromMirrorCsv", () => {
  it("dedupes a code used by several entities; current wins over historical rows", () => {
    const entries = fromMirrorCsv(
      header +
        "FRANCE,Euro,EUR,978,2,\nGERMANY,Euro,EUR,978,2,\n" +
        "SIERRA LEONE,Leone,SLE,925,2,\nSIERRA LEONE,Leone,SLL,694,,2023-12\n" +
        "ZZ08_Gold,Gold,XAU,959,-,\nANTARCTICA,No universal currency,,,,\n" +
        "CROATIA,Croatian Kuna,HRK,191,,2015-06\nCROATIA,Kuna,HRK,191,,2023-01\n",
    );
    expect(entries).toEqual([
      {
        code: "EUR",
        numeric: "978",
        name: "Euro",
        exponent: 2,
        historical: false,
        withdrawn: null,
      },
      {
        code: "HRK",
        numeric: "191",
        name: "Kuna",
        exponent: null,
        historical: true,
        withdrawn: "2023-01",
      },
      {
        code: "SLE",
        numeric: "925",
        name: "Leone",
        exponent: 2,
        historical: false,
        withdrawn: null,
      },
      {
        code: "SLL",
        numeric: "694",
        name: "Leone",
        exponent: null,
        historical: true,
        withdrawn: "2023-12",
      },
      {
        code: "XAU",
        numeric: "959",
        name: "Gold",
        exponent: null,
        historical: false,
        withdrawn: null,
      },
    ]);
  });

  it("trims names and collapses leading, trailing, doubled and no-break spaces", () => {
    const entries = fromMirrorCsv(
      header +
        "COMOROS (THE),Comorian Franc ,KMF,174,0,\n" +
        "X,  Two   Spaces  ,AAA,001,2,\n" +
        "ZIMBABWE,Zimbabwe\u00a0Dollar,ZWL,932,,2024-09\n" +
        'X,"\tTab\t\tName\t",BBB,002,2,\n',
    );
    expect(entries.map((e) => [e.code, e.name])).toEqual([
      ["AAA", "Two Spaces"],
      ["BBB", "Tab Name"],
      ["KMF", "Comorian Franc"],
      ["ZWL", "Zimbabwe Dollar"],
    ]);
  });

  it("compares normalised names, so rows differing only in whitespace do not conflict", () => {
    expect(
      fromMirrorCsv(
        header + "FRANCE,Euro ,EUR,978,2,\nGERMANY, Euro,EUR,978,2,\n",
      ).map((e) => e.name),
    ).toEqual(["Euro"]);
  });

  it("fails when two current rows for one code disagree", () => {
    expect(() =>
      fromMirrorCsv(
        header + "FRANCE,Euro,EUR,978,2,\nGERMANY,Euro,EUR,978,3,\n",
      ),
    ).toThrow(/conflicting/);
  });

  it("fails on a header it does not know", () => {
    expect(() => fromMirrorCsv("a,b\n1,2\n")).toThrow(/header/);
  });

  it("fails on a malformed code, numeric code or minor unit", () => {
    expect(() => fromMirrorCsv(header + "X,Euro,eur,978,2,\n")).toThrow();
    expect(() => fromMirrorCsv(header + "X,Euro,EUR,97,2,\n")).toThrow();
    expect(() => fromMirrorCsv(header + "X,Euro,EUR,978,x,\n")).toThrow();
  });
});

// The SIX XML layout (element names as published in list-one.xml and
// list-three.xml); two made-up rows, used only to test the parser.
const sixListOne = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<ISO_4217 Pblshd="2026-01-01">
<CcyTbl>
<CcyNtry><CtryNm>JAPAN</CtryNm><CcyNm>Yen</CcyNm><Ccy>JPY</Ccy><CcyNbr>392</CcyNbr><CcyMnrUnts>0</CcyMnrUnts></CcyNtry>
<CcyNtry><CtryNm>ZZ08_Gold</CtryNm><CcyNm>Gold</CcyNm><Ccy>XAU</Ccy><CcyNbr>959</CcyNbr><CcyMnrUnts>N.A.</CcyMnrUnts></CcyNtry>
<CcyNtry><CtryNm>CHILE</CtryNm><CcyNm IsFund="true">Unidad de Fomento</CcyNm><Ccy>CLF</Ccy><CcyNbr>990</CcyNbr><CcyMnrUnts>4</CcyMnrUnts></CcyNtry>
<CcyNtry><CtryNm>ANTARCTICA</CtryNm><CcyNm>No universal currency</CcyNm></CcyNtry>
</CcyTbl>
</ISO_4217>`;
const sixListThree = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<ISO_4217 Pblshd="2026-01-01">
<HstrcCcyTbl>
<HstrcCcyNtry><CtryNm>SIERRA LEONE</CtryNm><CcyNm>Leone</CcyNm><Ccy>SLL</Ccy><CcyNbr>694</CcyNbr><WthdrwlDt>2023-12</WthdrwlDt></HstrcCcyNtry>
<HstrcCcyNtry><CtryNm>JAPAN</CtryNm><CcyNm>Old Yen</CcyNm><Ccy>JPY</Ccy><CcyNbr>392</CcyNbr><WthdrwlDt>1900-01</WthdrwlDt></HstrcCcyNtry>
</HstrcCcyTbl>
</ISO_4217>`;

describe("fromSixXml (the owner's --source six cross-check)", () => {
  it("parses list-one and list-three into the same entry shape", () => {
    expect(fromSixXml(sixListOne, sixListThree)).toEqual([
      {
        code: "CLF",
        numeric: "990",
        name: "Unidad de Fomento",
        exponent: 4,
        historical: false,
        withdrawn: null,
      },
      {
        code: "JPY",
        numeric: "392",
        name: "Yen",
        exponent: 0,
        historical: false,
        withdrawn: null,
      },
      {
        code: "SLL",
        numeric: "694",
        name: "Leone",
        exponent: null,
        historical: true,
        withdrawn: "2023-12",
      },
      {
        code: "XAU",
        numeric: "959",
        name: "Gold",
        exponent: null,
        historical: false,
        withdrawn: null,
      },
    ]);
  });

  it("decodes XML entities in names", () => {
    const one = sixListOne.replace(
      "<CcyNm>Yen</CcyNm>",
      "<CcyNm>Yen &amp; Sen</CcyNm>",
    );
    expect(fromSixXml(one, sixListThree)[1]?.name).toBe("Yen & Sen");
  });

  it("normalises names the same way as fromMirrorCsv", () => {
    const one = sixListOne
      .replace("<CcyNm>Yen</CcyNm>", "<CcyNm>  Japanese   Yen </CcyNm>")
      .replace("<CcyNm>Gold</CcyNm>", "<CcyNm>Gold\u00a0Bullion</CcyNm>");
    const three = sixListThree.replace(
      "<CcyNm>Leone</CcyNm>",
      "<CcyNm>Old\u00a0\u00a0Leone </CcyNm>",
    );
    expect(fromSixXml(one, three).map((e) => [e.code, e.name])).toEqual([
      ["CLF", "Unidad de Fomento"],
      ["JPY", "Japanese Yen"],
      ["SLL", "Old Leone"],
      ["XAU", "Gold Bullion"],
    ]);
  });

  it("fails when list-one has no entries", () => {
    expect(() => fromSixXml("<ISO_4217/>", sixListThree)).toThrow(/no entries/);
  });
});

describe("compareEntries", () => {
  it("finds no difference between a mirror CSV and SIX XML that differ only in name whitespace", () => {
    const xml = `<ISO_4217 Pblshd="2026-09-17"><CcyTbl>
<CcyNtry><CtryNm>COMOROS (THE)</CtryNm><CcyNm>Comorian Franc </CcyNm><Ccy>KMF</Ccy><CcyNbr>174</CcyNbr><CcyMnrUnts>0</CcyMnrUnts></CcyNtry>
</CcyTbl></ISO_4217>`;
    const xmlThree = `<ISO_4217><HstrcCcyTbl>
<HstrcCcyNtry><CtryNm>ZIMBABWE</CtryNm><CcyNm>Zimbabwe  Dollar</CcyNm><Ccy>ZWL</Ccy><CcyNbr>932</CcyNbr><WthdrwlDt>2024-09</WthdrwlDt></HstrcCcyNtry>
</HstrcCcyTbl></ISO_4217>`;
    const mirror = fromMirrorCsv(
      header +
        "COMOROS (THE),Comorian Franc ,KMF,174,0,\n" +
        "ZIMBABWE,Zimbabwe\u00a0Dollar,ZWL,932,,2024-09\n",
    );
    expect(compareEntries(mirror, fromSixXml(xml, xmlThree))).toEqual([]);
  });

  it("is empty for equal lists and names each kind of difference", () => {
    const a = fromSixXml(sixListOne, sixListThree);
    expect(compareEntries(a, a)).toEqual([]);
    const b = a
      .filter((e) => e.code !== "XAU")
      .map((e) => (e.code === "JPY" ? { ...e, exponent: 2 } : e));
    expect(compareEntries(a, b)).toEqual([
      "JPY: exponent 0 -> 2",
      "XAU: only in the committed file",
    ]);
    expect(compareEntries(b, a)).toEqual([
      "JPY: exponent 2 -> 0",
      "XAU: only in the new source",
    ]);
  });
});
